//! Unicode 18 property changes relative to the ICU4X 2.1 bundled data.
//!
//! Generated by comparing `icu_properties` 2.1.2 with 2.3.0 plus
//! `icu_properties_data` from unicode-org/icu4x at
//! d1bf2f27ddeabbb61ee50f7cf1dac151aaa0d692 (Unicode 18.0.0).
//! Remove these overrides when a released ICU4X data crate contains Unicode 18.

pub const VERSION: (u8, u8, u8) = (18, 0, 0);

type Range = (u32, u32, &'static str);

fn lookup(cp: u32, ranges: &'static [Range]) -> Option<&'static str> {
    let index = ranges.partition_point(|(start, _, _)| *start <= cp);
    let (_, end, value) = ranges.get(index.checked_sub(1)?)?;
    (cp <= *end).then_some(*value)
}

