pub fn script(cp: u32) -> Option<&'static str> {
    lookup(cp, SCRIPT)
}

pub fn script_extensions(cp: u32) -> Option<&'static str> {
    lookup(cp, SCRIPT_EXTENSIONS)
}

pub fn general_category(cp: u32) -> Option<&'static str> {
    lookup(cp, GENERAL_CATEGORY)
}

pub fn bidi_class(cp: u32) -> Option<&'static str> {
    lookup(cp, BIDI_CLASS)
}

pub fn is_new_script(short_name: &str) -> bool {
    matches!(short_name, "Jurc" | "Pcun" | "Seal")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ranges_are_sorted_and_nonoverlapping() {
        for ranges in [SCRIPT, SCRIPT_EXTENSIONS, GENERAL_CATEGORY, BIDI_CLASS] {
            assert!(
                ranges
                    .windows(2)
                    .all(|window| matches!(window, [first, second] if first.1 < second.0))
            );
        }
    }
}
